import { readFile, writeFile, mkdir } from "node:fs/promises";

// Generate a one-time migration. Existing product/variant/stock records are never reset.
const items = JSON.parse(await readFile("db/inventory-list.json", "utf8"));
const sources = JSON.parse(
  await readFile("db/inventory-image-sources.json", "utf8"),
);
const quote = (value) => `'${String(value).replaceAll("'", "''")}'`;
const statements = [
  "-- Owner inventory, October 2026. New variants start with zero stock.",
  "-- Generated by scripts/build-owner-inventory.mjs; do not replay as a catalogue sync.",
  "INSERT OR IGNORE INTO categories(id,name,slug,description,active) VALUES('handhelds','Handhelds','handhelds','Portable consoles and PC gaming handhelds.',1),('vr','VR headsets','vr','Virtual reality headsets.',1);",
];
const report = [];
for (const item of items) {
  const pictures = sources.filter((source) => source.productSlug === item.slug);
  const reasons = [
    item.review,
    !pictures.length && "Exact transparent product photograph pending.",
  ].filter(Boolean);
  const published = reasons.length === 0;
  const description = `${item.name}. Choose the available ${item.options.length > 1 ? "condition and configuration" : "configuration"} below. Confirm supplied accessories and package contents with the store.`;
  const product = `(SELECT id FROM products WHERE slug=${quote(item.slug)})`;
  statements.push(
    `INSERT OR IGNORE INTO products(id,slug,name,description,category_id,brand,platform,condition,product_type,featured,active,demo,seo_title,seo_description) VALUES(${[item.id, item.slug, item.name, description].map(quote).join(",")},(SELECT id FROM categories WHERE slug=${quote(item.category)}),${[item.brand, item.platform, item.condition, item.type].map(quote).join(",")},0,${Number(published)},0,${quote(item.name + " in Pakistan")},${quote(description)});`,
    `INSERT OR IGNORE INTO product_details(product_id,generation,edition,price_on_request) VALUES(${product},${quote(item.generation)},${quote(item.name.split(" - ")[1] || "")},0);`,
  );
  item.options.forEach((option, index) => {
    const id = `${item.id}-v${index + 1}`;
    // A pre-existing single-option product already has its own SKU and owner-edited price.
    const guard =
      item.options.length === 1
        ? `NOT EXISTS(SELECT 1 FROM product_variants WHERE product_id=${product})`
        : `NOT EXISTS(SELECT 1 FROM product_variants WHERE product_id=${product} AND name=${quote(option.name)} AND coalesce(condition,${quote(item.condition)})=${quote(option.condition)})`;
    statements.push(
      `INSERT OR IGNORE INTO product_variants(id,product_id,sku,name,attributes_json,price_pkr,available,condition) SELECT ${quote(id)},${product},${quote("GFP-INV-" + item.slug.toUpperCase() + "-" + (index + 1))},${quote(option.name)},${quote(JSON.stringify({ Configuration: option.name }))},${item.type === "controller" ? 21999 : 249999},1,${quote(option.condition)} WHERE ${guard};`,
    );
  });
  // Include the existing SKU when reusing an owner-managed product, without altering its counts.
  statements.push(
    `INSERT OR IGNORE INTO inventory(id,variant_id,branch_id,quantity_available) SELECT 'owner-inventory-'||v.id||'-'||b.id,v.id,b.id,0 FROM product_variants v CROSS JOIN branches b WHERE v.product_id=${product};`,
  );
  pictures.forEach((picture, index) => {
    const variant = picture.optionName
      ? `(SELECT id FROM product_variants WHERE product_id=${product} AND name=${quote(picture.optionName)} LIMIT 1)`
      : "NULL";
    statements.push(
      `INSERT OR IGNORE INTO product_images(id,product_id,variant_id,r2_key,alt_text,display_order,is_primary,is_transparent_asset,is_showcase_asset,width,height) SELECT ${quote(item.id + "-inventory-image-" + (index + 1))},${product},${variant},${quote(picture.key)},${quote(item.name + (picture.optionName ? " - " + picture.optionName : "") + " product image")},${index},CASE WHEN NOT EXISTS(SELECT 1 FROM product_images WHERE product_id=${product} AND is_primary=1) THEN 1 ELSE 0 END,1,1,${picture.width},${picture.height};`,
    );
  });
  report.push({
    slug: item.slug,
    name: item.name,
    status: published ? "Ready" : "Draft",
    options: item.options.length,
    reasons: reasons.join(" "),
  });
}
// Retire only the two known opaque seed packshots; keep any owner-selected photo.
statements.push(
  "UPDATE product_images SET is_primary=0 WHERE r2_key IN ('catalogue/dualsense-midnight-black.png','catalogue/dualsense-cosmic-red.png') AND product_id IN ('catalog-dualsense-midnight-black','catalog-dualsense-cosmic-red');",
  "UPDATE product_images SET is_primary=1 WHERE r2_key IN ('catalogue/inventory-dualsense-midnight-black.webp','catalogue/inventory-dualsense-cosmic-red.webp') AND NOT EXISTS(SELECT 1 FROM product_images current_image WHERE current_image.product_id=product_images.product_id AND current_image.is_primary=1);",
);
await writeFile(
  "db/migrations/0012_owner_inventory.sql",
  statements.join("\n") + "\n",
);
await writeFile(
  "db/inventory-review.json",
  JSON.stringify(report, null, 2) + "\n",
);
const ready = report.filter((item) => item.status === "Ready").length;
await mkdir("docs", { recursive: true });
await writeFile(
  "docs/inventory-import.md",
  `# Owner inventory import\n\n${items.length} requested listings, ${items.reduce((count, item) => count + item.options.length, 0)} requested configurations. ${ready} ready; ${items.length - ready} drafts. Existing products keep their publication status, pricing and stock. New variants have zero stock and use PKR 21,999 for controllers or PKR 249,999 for consoles, handhelds and VR headsets.\n\nThe one-time D1 migration runs through the existing deployment workflow. Owner changes are not synchronized or overwritten by this JSON after migration. Branch inventory is created for each new variant. The owner can change price, stock, photos and publication in /admin.\n\n## Draft review\n\n| Product | Reason |\n| --- | --- |\n${report
    .filter((item) => item.status === "Draft")
    .map((item) => `| ${item.name} | ${item.reasons} |`)
    .join(
      "\n",
    )}\n\n## Image sources\n\nSource URLs, attribution and processing notes are recorded in db/inventory-image-sources.json. Local WebP files retain transparency and receive responsive delivery sizes during the normal build. Manufacturer images illustrate model/design, not the cosmetic condition of an individual pre-owned unit.\n\nFor ShareAlike photographs, the linked image file remains under the source licence. Processing is limited to resizing/compression unless the source record explicitly says otherwise.\n`,
);
console.log(
  `${items.length} products, ${ready} ready, ${items.length - ready} drafts.`,
);
